package teamroots.embers.research.capability;

import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumFacing;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.capabilities.CapabilityInject;
import net.minecraftforge.common.capabilities.ICapabilityProvider;
import net.minecraftforge.common.util.INBTSerializable;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;

public class ResearchCapabilityProvider implements ICapabilityProvider, INBTSerializable<NBTTagCompound> {
    private IResearchCapability capability = null;

    public ResearchCapabilityProvider(){
        capability = new DefaultResearchCapability();
    }

    public ResearchCapabilityProvider(IResearchCapability capability){
        this.capability = capability;
    }

    @CapabilityInject(IResearchCapability.class)
    public static final Capability<IResearchCapability> researchCapability = null;

    @Override
    public boolean hasCapability(@Nonnull Capability<?> capability, @Nullable EnumFacing facing) {
        return capability == researchCapability;
    }

    @Nullable
    @Override
    public <T> T getCapability(@Nonnull Capability<T> capability, @Nullable EnumFacing facing) {
        if (researchCapability != null && capability == researchCapability)
            return researchCapability.cast(this.capability);
        return null;
    }

    @Override
    public NBTTagCompound serializeNBT() {
        NBTTagCompound compound = new NBTTagCompound();
        capability.writeToNBT(compound);
        return compound;
    }

    @Override
    public void deserializeNBT(NBTTagCompound compound) {
        capability.readFromNBT(compound);
    }
}

package com.Polarice3.Goety.common.capabilities.soulenergy;

import com.Polarice3.Goety.common.network.ModNetwork;
import com.Polarice3.Goety.common.network.server.SFocusCooldownPacket;
import com.Polarice3.Goety.common.network.server.SFocusSpecificCooldownPacket;
import com.google.common.collect.Maps;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraftforge.registries.ForgeRegistries;

import java.util.Iterator;
import java.util.Map;

/**
 * Made custom cooldown mechanic based of vanilla item cooldowns for any future tinkering. And also to prevent an exploit where relogging can reset item cooldown.".
 */
public class FocusCooldown {
    public final Map<Item, CooldownInstance> cooldowns = Maps.newHashMap();
    public final Map<String, CooldownInstance> cooldownsSpecific = Maps.newHashMap();

    public static String keyOf(ItemStack stack) {
        ResourceLocation location = ForgeRegistries.ITEMS.getKey(stack.getItem());
        if (location != null) {
            String base = location.toString();
            return stack.getTag() != null ? base + stack.getTag() : base;
        }
        return "minecraft:air";
    }

    public boolean isOnSpecificCooldown(ItemStack itemStack) {
        return this.getSpecificCooldownPercent(itemStack) > 0.0F;
    }

    public boolean isOnCooldown(Item item) {
        return this.getCooldownPercent(item) > 0.0F;
    }

    public float getCooldownPercent(Item item) {
        CooldownInstance cooldownInstance = this.cooldowns.get(item);
        if (cooldownInstance != null) {
            return Mth.clamp((float) cooldownInstance.time / cooldownInstance.totalTime, 0.0F, 1.0F);
        } else {
            return 0.0F;
        }
    }

    public float getSpecificCooldownPercent(ItemStack itemStack) {
        CooldownInstance cooldownInstance = this.cooldownsSpecific.get(keyOf(itemStack));
        if (cooldownInstance != null) {
            return Mth.clamp((float) cooldownInstance.time / cooldownInstance.totalTime, 0.0F, 1.0F);
        }
        return 0.0F;
    }

    public void tick(Player player, Level level) {
        if (!this.cooldowns.isEmpty()) {
            Iterator<Map.Entry<Item, CooldownInstance>> iterator = this.cooldowns.entrySet().iterator();

            while(iterator.hasNext()) {
                Map.Entry<Item, CooldownInstance> entry = iterator.next();
                entry.getValue().decreaseTime();
                if (entry.getValue().time <= 0) {
                    iterator.remove();
                    if (!level.isClientSide) {
                        this.onCooldownEnded(player, entry.getKey());
                    }
                }
            }
        }
        if (!this.cooldownsSpecific.isEmpty()) {
            Iterator<Map.Entry<String, CooldownInstance>> iterator = this.cooldownsSpecific.entrySet().iterator();

            while(iterator.hasNext()) {
                Map.Entry<String, CooldownInstance> entry = iterator.next();
                entry.getValue().decreaseTime();
                if (entry.getValue().time <= 0) {
                    iterator.remove();
                    if (!level.isClientSide) {
                        this.onSpecificCooldownEnded(player, entry.getKey());
                    }
                }
            }
        }
    }

    public void addCooldown(Player player, Level level, Item item, int coolDown) {
        this.cooldowns.put(item, new CooldownInstance(coolDown));
        if (!level.isClientSide) {
            this.onCooldownStarted(player, item, coolDown);
        }
    }

    public void addSpecificCooldown(Player player, Level level, ItemStack itemStack, int coolDown) {
        this.cooldownsSpecific.put(keyOf(itemStack), new CooldownInstance(coolDown));
        if (!level.isClientSide) {
            this.onSpecificCooldownStarted(player, itemStack, coolDown);
        }
    }

    public void removeCooldown(Player player, Level level, Item item) {
        this.cooldowns.remove(item);
        if (!level.isClientSide) {
            this.onCooldownEnded(player, item);
        }
    }

    public void removeSpecificCooldown(Player player, Level level, ItemStack itemStack) {
        this.cooldownsSpecific.remove(keyOf(itemStack));
        if (!level.isClientSide) {
            this.onSpecificCooldownEnded(player, itemStack);
        }
    }

    public void removeSpecificCooldown(Player player, Level level, String string) {
        this.cooldownsSpecific.remove(string);
        if (!level.isClientSide) {
            this.onSpecificCooldownEnded(player, string);
        }
    }

    protected void onCooldownStarted(Player player, Item item, int duration) {
        ModNetwork.sendTo(player, new SFocusCooldownPacket(item, duration));
    }

    protected void onSpecificCooldownStarted(Player player, ItemStack itemStack, int duration) {
        ModNetwork.sendTo(player, new SFocusSpecificCooldownPacket(itemStack, duration));
    }

    protected void onCooldownEnded(Player player, Item item) {
        ModNetwork.sendTo(player, new SFocusCooldownPacket(item, 0));
    }

    protected void onSpecificCooldownEnded(Player player, String key) {
        ModNetwork.sendTo(player, new SFocusSpecificCooldownPacket(key, 0));
    }

    protected void onSpecificCooldownEnded(Player player, ItemStack itemStack) {
        onSpecificCooldownEnded(player, keyOf(itemStack));
    }

    public CooldownInstance getInstance(Item item){
        return this.cooldowns.get(item);
    }

    public void setCooldown(Item item, CooldownInstance cooldownInstance){
        this.cooldowns.put(item, cooldownInstance);
    }

    public Map<Item, CooldownInstance> getCooldowns(){
        return this.cooldowns;
    }

    public Map<String, CooldownInstance> getSpecificCooldowns(){
        return this.cooldownsSpecific;
    }

    public void save(ListTag listTag) {
        cooldowns.forEach((item, cooldown) -> {
            if (isOnCooldown(item)) {
                CompoundTag compoundTag = new CompoundTag();
                compoundTag.putInt("Item", Item.getId(item));
                compoundTag.putInt("Time", cooldown.time);
                compoundTag.putInt("TotalTime", cooldown.totalTime);
                listTag.add(compoundTag);
            }
        });
    }

    public void saveSpecifics(ListTag listTag) {
        cooldownsSpecific.forEach((key, cooldown) -> {
            if (cooldown.time > 0) {
                CompoundTag compoundTag = new CompoundTag();
                compoundTag.putString("Key", key);
                compoundTag.putInt("Time", cooldown.time);
                compoundTag.putInt("TotalTime", cooldown.totalTime);
                listTag.add(compoundTag);
            }
        });
    }

    public void load(ListTag listTag){
        if (listTag != null) {
            listTag.forEach(tag -> {
                CompoundTag compoundTag = (CompoundTag) tag;
                Item item = Item.byId(compoundTag.getInt("Item"));
                int startTime = compoundTag.getInt("Time");
                int endTime = compoundTag.getInt("TotalTime");
                cooldowns.put(item, new CooldownInstance(startTime, endTime));
            });
        }
    }

    public void loadSpecifics(ListTag listTag){
        if (listTag != null) {
            listTag.forEach(tag -> {
                CompoundTag compoundTag = (CompoundTag) tag;
                String key = compoundTag.getString("Key");
                int startTime = compoundTag.getInt("Time");
                int endTime = compoundTag.getInt("TotalTime");
                cooldownsSpecific.put(key, new CooldownInstance(startTime, endTime));
            });
        }
    }

    public static class CooldownInstance {
        int time;
        final int totalTime;

        public CooldownInstance(int time){
            this(time, time);
        }

        public CooldownInstance(int time, int totalTime) {
            this.time = time;
            this.totalTime = totalTime;
        }

        public void decreaseTime(){
            if (this.time > 0){
                --this.time;
            }
        }
    }
}

package de.teamlapen.vampirism.common.world.blockentity;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import de.teamlapen.vampirism.common.world.inventory.base.PlayerOwnedMenu;
import net.minecraft.core.BlockPos;
import net.minecraft.core.UUIDUtil;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.util.StringRepresentable;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.block.entity.BaseContainerBlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.common.util.ValueIOSerializable;
import net.neoforged.neoforge.network.codec.NeoForgeStreamCodecs;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.Optional;
import java.util.UUID;

public abstract class PlayerOwnedBlockEntity extends BaseContainerBlockEntity {

    private final LockDataHolder lockDataHolder = new LockDataHolder();

    protected PlayerOwnedBlockEntity(BlockEntityType<?> pType, BlockPos pPos, BlockState pBlockState) {
        super(pType, pPos, pBlockState);
    }

    public void setOwned(Player player) {
        this.lockDataHolder.owner = player.getUUID();
    }

    public static boolean tryAccess(Player player, PlayerOwnedBlockEntity blockEntity, Component displayName) {
        return player.isSpectator() || blockEntity.lockDataHolder.canAccess(player);
    }

    @Override
    public boolean canOpen(@NotNull Player pPlayer) {
        return super.canOpen(pPlayer) && tryAccess(pPlayer, this, this.getName());
    }

    @Override
    protected void saveAdditional(@NotNull ValueOutput output) {
        super.saveAdditional(output);
        this.lockDataHolder.serialize(output.child("lock"));
    }

    @Override
    public void loadAdditional(@NotNull ValueInput input) {
        super.loadAdditional(input);
        this.lockDataHolder.deserialize(input.childOrEmpty("lock"));
    }

    @Override
    protected final @NotNull PlayerOwnedMenu createMenu(int pContainerId, @NotNull Inventory pInventory) {
        return createMenu(pContainerId, pInventory, lockDataHolder);
    }

    protected abstract PlayerOwnedMenu createMenu(int pContainerId, @NotNull Inventory pInventory, @NotNull LockDataHolder lockData);

    public void writeExtraData(FriendlyByteBuf buffer) {
        this.lockDataHolder.writeToBuffer(buffer);
    }

    public static class LockDataHolder implements ValueIOSerializable {
        public static final Codec<LockDataHolder> CODEC = RecordCodecBuilder.create(inst ->
                inst.group(
                        Codec.STRING.xmap(UUID::fromString, UUID::toString).optionalFieldOf("owner").forGetter(l -> java.util.Optional.ofNullable(l.owner)),
                        StringRepresentable.fromEnum(Lock::values).fieldOf("lockStatus").forGetter(LockDataHolder::getLockStatus)
                ).apply(inst, LockDataHolder::new)
        );
        public static final StreamCodec<FriendlyByteBuf, LockDataHolder> STREAM_CODEC = StreamCodec.composite(
                ByteBufCodecs.optional(UUIDUtil.STREAM_CODEC), o -> Optional.ofNullable(o.getOwner()),
                NeoForgeStreamCodecs.enumCodec(Lock.class), LockDataHolder::getLockStatus,
                LockDataHolder::new
        );

        private @Nullable UUID owner;
        private Lock lockStatus = Lock.PUBLIC;

        public LockDataHolder() {
        }

        public LockDataHolder(Lock lockStatus) {
            this.lockStatus = lockStatus;
        }

        @SuppressWarnings("OptionalUsedAsFieldOrParameterType")
        private LockDataHolder(Optional<UUID> owner, Lock lockStatus) {
            this.owner = owner.orElse(null);
            this.lockStatus = lockStatus;
        }

        public @Nullable UUID getOwner() {
            return owner;
        }

        public Lock getLockStatus() {
            return lockStatus;
        }

        public boolean canAccess(Player player) {
            return this.lockStatus == Lock.PUBLIC || this.isOwner(player);
        }

        public boolean isOwner(Player player) {
            return this.owner != null && this.owner.equals(player.getUUID());
        }

        @Override
        public void serialize(ValueOutput output) {
            if (this.owner != null) {
                output.store("owner", UUIDUtil.CODEC, this.owner);
                output.store("lock", Lock.CODEC, this.lockStatus);
            }
        }

        @Override
        public void deserialize(ValueInput input) {
            input.read("owner", UUIDUtil.CODEC).ifPresentOrElse(uuid -> {
                this.owner = uuid;
                this.lockStatus = input.read("lock", Lock.CODEC).orElse(Lock.PUBLIC);
            }, () -> this.lockStatus = Lock.PUBLIC);
        }

        private void writeToBuffer(FriendlyByteBuf buffer) {
            buffer.writeBoolean(this.owner != null);
            if (owner != null) {
                buffer.writeUUID(this.owner);
                buffer.writeEnum(this.lockStatus);
            }
        }

        private void readFromBuffer(FriendlyByteBuf buffer) {
            if (buffer.readBoolean()) {
                this.owner = buffer.readUUID();
                this.lockStatus = buffer.readEnum(Lock.class);
            }
        }

        public static LockDataHolder createFromBuffer(FriendlyByteBuf buffer) {
            var holder = new LockDataHolder();
            holder.readFromBuffer(buffer);
            return holder;
        }

        public void updateStatus(Player player, Lock lockStatus) {
            if (this.isOwner(player)) {
                this.lockStatus = lockStatus;
            }
        }
    }

    public enum Lock implements StringRepresentable {
        PUBLIC("public"),
        PRIVATE("private");

        public static final Codec<Lock> CODEC = StringRepresentable.fromEnum(Lock::values);

        private final String name;

        Lock(String name) {
            this.name = name;
        }

        @Override
        public @NotNull String getSerializedName() {
            return this.name;
        }

        public static Lock get(String key) {
            for (Lock value : values()) {
                if (value.name.equals(key)) {
                    return value;
                }
            }
            return PUBLIC;
        }
    }
}

package com.teamwizardry.wizardry.api.capability.player.miscdata;

import com.teamwizardry.librarianlib.features.network.PacketHandler;
import com.teamwizardry.wizardry.common.entity.EntityFairy;
import com.teamwizardry.wizardry.common.network.capability.PacketUpdateMiscCapToClient;
import net.minecraft.entity.Entity;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.world.World;

import javax.annotation.Nullable;
import java.util.UUID;

public class DefaultMiscCapability implements IMiscCapability {

	@Nullable
	private UUID selectedFairy = null;

	private int spawnedBackup = 0;

	@Override
	public void setSelectedFairy(@Nullable UUID selectedFairy) {
		this.selectedFairy = selectedFairy;
	}

	@Override
	@Nullable
	public EntityFairy getSelectedFairyEntity(World world) {
		if (selectedFairy == null) return null;

		for (EntityFairy entityFairy : world.getEntities(EntityFairy.class, input -> {
			if (input != null) {
				return input.getUniqueID().equals(selectedFairy);
			}
			return false;
		})) {
			if (entityFairy.getUniqueID().equals(selectedFairy)) return entityFairy;
		}

		return null;
	}

	@Nullable
	@Override
	public UUID getSelectedFairyUUID() {
		return selectedFairy;
	}

	@Override
	public NBTTagCompound serializeNBT() {
		return (NBTTagCompound) MiscCapabilityStorage.INSTANCE.writeNBT(MiscCapabilityProvider.miscCapability, this, null);
	}

	@Override
	public void deserializeNBT(NBTTagCompound compound) {
		MiscCapabilityStorage.INSTANCE.readNBT(MiscCapabilityProvider.miscCapability, this, null, compound);
	}

	@Override
	public void dataChanged(Entity entity) {
		if (entity instanceof EntityPlayer && !entity.getEntityWorld().isRemote)
			PacketHandler.NETWORK.sendTo(new PacketUpdateMiscCapToClient(serializeNBT()), (EntityPlayerMP) entity);
	}
}
